Here's a Python program that meets your requirements. This program uses a class to represent the bank account, and it includes methods for depositing, withdrawing, checking balance, and displaying transaction history. The main part of the program uses a while loop to continuously prompt the user for input until they choose to exit.

```python
class BankAccount:
    def __init__(self, balance=0):
        self.balance = balance
        self.transaction_history = []

    def deposit(self, amount):
        if amount > 0:
            self.balance += amount
            self.transaction_history.append(f"Deposit: {amount}")
        else:
            print("Deposit amount must be positive.")

    def withdraw(self, amount):
        if amount > 0 and self.balance >= amount:
            self.balance -= amount
            self.transaction_history.append(f"Withdrawal: {amount}")
        else:
            print("Insufficient funds or withdrawal amount must be positive.")

    def check_balance(self):
        print(f"Balance: {self.balance}")

    def display_transaction_history(self):
        print("\nTransaction history:")
        for i, transaction in enumerate(self.transaction_history, start=1):
            print(f"{i}. {transaction}")


def main():
    account = BankAccount()

    while True:
        print("1. Deposit")
        print("2. Withdraw")
        print("3. Check Balance")
        print("4. Display Transaction History")
        print("5. Exit")

        option = int(input("Enter your choice: "))

        if option == 5:
            break

        command = input("Enter command: ").lower()

        if command == "deposit":
            amount = float(input("Enter deposit amount: "))
            account.deposit(amount)
        elif command == "withdraw":
            amount = float(input("Enter withdrawal amount: "))
            account.withdraw(amount)
        elif command == "check balance":
            account.check_balance()
        elif command == "display transaction history":
            account.display_transaction_history()
        else:
            print("Invalid command. Please try again.")


if __name__ == "__main__":
    main()
